import { test, expect } from '@playwright/test';

test.describe('JavaScript Error Recovery', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should recover gracefully after a JavaScript error and display error message', async ({ page }) => {
    // Trigger a JavaScript error by clicking a button that causes an error
    const errorButton = page.getByRole('button', { name: /trigger error/i });
    await errorButton.click();

    // Wait for error state
    await page.waitForTimeout(500);

    // Verify error state is visible
    const errorMessage = page.getByText(/unexpected error/i);
    await expect(errorMessage).toBeVisible();

    // Verify navigation button is still accessible
    const navigationButton = page.getByRole('button', { name: /go back/i });
    await expect(navigationButton).toBeVisible();

    // Verify navigation button is enabled
    await expect(navigationButton).toBeEnabled();

    // Verify error message contains recovery instructions
    await expect(errorMessage).toContainText(/retry/i);

    // Verify application state is preserved
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    // Verify data is still displayed
    const dataTable = page.getByRole('table');
    await expect(dataTable).toBeVisible();

    // Verify error message is dismissible
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify error message is dismissed on click
    await dismissButton.click();
    await expect(errorMessage).not.toBeVisible();

    // Verify application returns to normal state
    await expect(dashboardTitle).toBeVisible();
    await expect(dataTable).toBeVisible();

    // Verify navigation button is still accessible after recovery
    await expect(navigationButton).toBeVisible();
  });

  test('should handle multiple consecutive JavaScript errors and display recovery message', async ({ page }) => {
    // Trigger first JavaScript error
    const errorButton1 = page.getByRole('button', { name: /trigger error/i });
    await errorButton1.click();

    // Wait for error state
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage1 = page.getByText(/unexpected error/i);
    await expect(errorMessage1).toBeVisible();

    // Verify navigation button is still accessible
    const navigationButton = page.getByRole('button', { name: /go back/i });
    await expect(navigationButton).toBeVisible();

    // Verify error message contains recovery instructions
    await expect(errorMessage1).toContainText(/retry/i);

    // Trigger second JavaScript error
    const errorButton2 = page.getByRole('button', { name: /trigger error/i });
    await errorButton2.click();

    // Wait for error state
    await page.waitForTimeout(500);

    // Verify error message is displayed again
    const errorMessage2 = page.getByText(/unexpected error/i);
    await expect(errorMessage2).toBeVisible();

    // Verify error message contains recovery instructions
    await expect(errorMessage2).toContainText(/retry/i);

    // Verify navigation button is still accessible
    await expect(navigationButton).toBeVisible();

    // Verify error message is dismissible
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify error message is dismissed on click
    await dismissButton.click();
    await expect(errorMessage2).not.toBeVisible();

    // Verify application returns to normal state
    await expect(dashboardTitle).toBeVisible();
    await expect(dataTable).toBeVisible();

    // Verify navigation button is still accessible after recovery
    await expect(navigationButton).toBeVisible();
  });
});
